import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var people = [['Анна Смирнова', 'Администратор', 'АС'], ['Иван Петров', 'Диспетчер', 'ИП'], ['Мария Волкова', 'Диспетчер', 'МВ']];
function LoadingList() {
    return <div className={'list'}>
        {people.map(function (_, i) {
            return <div className={'row'} key={i}>
            <S.DsSkeleton width={40} height={40} radius={'50%'}/>
            <div className={'text'}>
            <div className={'name-slot'}>
            <S.DsSkeleton width={[70, 90, 55][i] + '%'} height={14}/>
            </div>
            <div className={'detail-slot'}>
            <S.DsSkeleton width={'45%'} height={10}/>
            </div>
            </div>
            </div>;
        })}
    </div>;
}
function LoadingExample() {
    var loading = React.useState(true), timer = React.useRef(null), pending = React.useRef(false);
    function load() {
        if (pending.current)
            return;
        pending.current = true;
        loading[1](true);
        timer.current = setTimeout(function () { pending.current = false; loading[1](false); }, 1200);
    }
    React.useEffect(function () { load(); return function () { clearTimeout(timer.current); pending.current = false; }; }, []);
    return <div className={"demo-stack"}>
    <div className={'toolbar'}>
    <S.DsButton tone={'secondary'} onClick={load} aria-disabled={loading[0]}>
    {'Повторить загрузку'}
    </S.DsButton>
    </div>
    <div aria-busy={loading[0]} aria-label={'Пользователи'} role={'region'}>
    {loading[0] ? <LoadingList /> : <div className={'list'}>
    {people.map(function (person, i) {
                return <div className={'row'} key={i}>
    <span className={'avatar'} aria-hidden={true}>
    {person[2]}
    </span>
    <div className={'text'}>
    <div className={'name-slot'}>
    <span className={'name'}>
    {person[0]}
    </span>
    </div>
    <div className={'detail-slot'}>
    <span className={'detail'}>
    {person[1]}
    </span>
    </div>
    </div>
    </div>;
            })}
    </div>}
    </div>
    <p className={'status'} role={'status'}>
    {loading[0] ? 'Загрузка пользователей…' : 'Загружено 3 пользователя.'}
    </p>
    </div>;
}
function App() {
    return <div className="dsskeleton-example">
    <style>{exampleStyles}</style>
    <LoadingExample />
    </div>;
}

const exampleStyles = ".dsskeleton-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsskeleton-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsskeleton-example p{margin:0}\n.dsskeleton-example .list{display:flex;flex-direction:column;gap:16px;max-width:420px}\n.dsskeleton-example .row{display:flex;align-items:center;gap:12px;min-width:0;min-height:40px}\n.dsskeleton-example .row>span:first-child{flex:none}\n.dsskeleton-example .text{display:flex;flex-direction:column;gap:4px;flex:1;min-width:0}\n.dsskeleton-example .name-slot{height:20px;display:flex;align-items:center;min-width:0}\n.dsskeleton-example .detail-slot{height:16px;display:flex;align-items:center;min-width:0}\n.dsskeleton-example .name{font:var(--ds-type-body-strong);line-height:20px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.dsskeleton-example .detail{font:var(--ds-type-caption);line-height:16px;color:var(--ds-fg-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.dsskeleton-example .avatar{display:flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:50%;background:var(--ds-surface-active);color:var(--ds-fg-muted);flex:none}\n.dsskeleton-example .toolbar{margin-bottom:16px}\n.dsskeleton-example .status{font:var(--ds-type-caption);color:var(--ds-fg-muted);margin:12px 0 0}";

